"""OpenAI Agents SDK-shaped runtime in stdlib.

Five primitives: Agent, FunctionTool, Handoff, Guardrail, Tracing.
Handoffs are tools named transfer_to_<agent>. Guardrails trip on input/output.
A span tree mirrors what the real SDK emits.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable


class GuardrailTripped(Exception):
    def __init__(self, which: str, reason: str) -> None:
        super().__init__(f"{which}: {reason}")
        self.which = which
        self.reason = reason


@dataclass
class FunctionTool:
    name: str
    description: str
    fn: Callable[..., str]


@dataclass
class Handoff:
    target: "Agent"

    @property
    def tool_name(self) -> str:
        return f"transfer_to_{self.target.name}"


@dataclass
class Agent:
    name: str
    instructions: str
    policy: Callable[[str], dict[str, Any]]
    tools: list[FunctionTool] = field(default_factory=list)
    handoffs: list[Handoff] = field(default_factory=list)


@dataclass
class InputGuardrail:
    name: str
    check: Callable[[str], tuple[bool, str]]


@dataclass
class OutputGuardrail:
    name: str
    check: Callable[[str], tuple[bool, str]]


@dataclass
class Span:
    name: str
    attributes: dict[str, Any] = field(default_factory=dict)
    children: list["Span"] = field(default_factory=list)


@dataclass
class Runner:
    input_guardrails: list[InputGuardrail] = field(default_factory=list)
    output_guardrails: list[OutputGuardrail] = field(default_factory=list)
    max_hops: int = 3
    trace: Span = field(default_factory=lambda: Span(name="run"))

    def run(self, agent: Agent, user_input: str) -> str:
        for guard in self.input_guardrails:
            ok, reason = guard.check(user_input)
            span = Span(name=f"input_guardrail.{guard.name}",
                        attributes={"passed": ok, "reason": reason})
            self.trace.children.append(span)
            if not ok:
                raise GuardrailTripped("input", reason)

        current_agent = agent
        current_input = user_input
        final_output = ""
        for hop in range(self.max_hops):
            agent_span = Span(name=f"agent.{current_agent.name}",
                              attributes={"hop": hop,
                                          "instructions": current_agent.instructions[:40]})
            self.trace.children.append(agent_span)

            policy_output = current_agent.policy(current_input)
            kind = policy_output["kind"]

            if kind == "final":
                final_output = policy_output["text"]
                agent_span.children.append(
                    Span(name="llm_generation",
                         attributes={"output": final_output[:60]})
                )
                break
            if kind == "tool":
                tool_name = policy_output["tool"]
                args = policy_output.get("args", {})
                tool = next((t for t in current_agent.tools if t.name == tool_name),
                            None)
                if tool is None:
                    agent_span.children.append(
                        Span(name="tool_error",
                             attributes={"tool": tool_name,
                                         "reason": "unknown tool"})
                    )
                    final_output = f"error: unknown tool {tool_name}"
                    break
                result = tool.fn(**args)
                agent_span.children.append(
                    Span(name=f"tool.{tool_name}",
                         attributes={"args": args, "result": result[:40]})
                )
                current_input = f"tool {tool_name} returned: {result}"
                continue
            if kind == "handoff":
                target_name = policy_output["to"]
                handoff = next((h for h in current_agent.handoffs
                                if h.target.name == target_name), None)
                if handoff is None:
                    final_output = f"error: no handoff to {target_name}"
                    break
                agent_span.children.append(
                    Span(name=f"handoff.{handoff.tool_name}",
                         attributes={"from": current_agent.name,
                                     "to": target_name})
                )
                current_agent = handoff.target
                current_input = policy_output.get("input", current_input)
                continue
            final_output = f"error: unknown policy kind {kind}"
            break

        for guard in self.output_guardrails:
            ok, reason = guard.check(final_output)
            span = Span(name=f"output_guardrail.{guard.name}",
                        attributes={"passed": ok, "reason": reason})
            self.trace.children.append(span)
            if not ok:
                raise GuardrailTripped("output", reason)

        return final_output


def _print_span(span: Span, indent: int = 0) -> None:
    prefix = "  " * indent
    attrs = " ".join(f"{k}={v!r}" for k, v in span.attributes.items())
    print(f"{prefix}{span.name}  {attrs}")
    for child in span.children:
        _print_span(child, indent + 1)


def _triage_policy(user_input: str) -> dict[str, Any]:
    t = user_input.lower()
    if "refund" in t or "billing" in t or "invoice" in t:
        return {"kind": "handoff", "to": "billing", "input": user_input}
    if "error" in t or "crash" in t or "bug" in t:
        return {"kind": "handoff", "to": "support", "input": user_input}
    return {"kind": "final", "text": "i'm not sure how to help with that"}


def _billing_policy(user_input: str) -> dict[str, Any]:
    return {"kind": "final", "text": f"billing handled: {user_input[:40]}"}


def _support_policy(user_input: str) -> dict[str, Any]:
    return {"kind": "final", "text": f"support handled: {user_input[:40]}"}


def _pii_check(text: str) -> tuple[bool, str]:
    if "ssn" in text.lower():
        return False, "refuses to process social security numbers"
    return True, "ok"


def _length_check(text: str) -> tuple[bool, str]:
    return len(text) < 200, f"output {len(text)} chars"


def main() -> None:
    print("=" * 70)
    print("OPENAI AGENTS SDK SHAPE: Phase 14, Lesson 16")
    print("=" * 70)

    billing = Agent(name="billing", instructions="handle refunds and invoices",
                    policy=_billing_policy)
    support = Agent(name="support", instructions="handle bugs and errors",
                    policy=_support_policy)
    triage = Agent(
        name="triage", instructions="route queries to the right specialist",
        policy=_triage_policy,
        handoffs=[Handoff(target=billing), Handoff(target=support)],
    )

    runner = Runner(
        input_guardrails=[InputGuardrail("pii_block", _pii_check)],
        output_guardrails=[OutputGuardrail("length_cap", _length_check)],
    )

    cases = [
        "I need a refund for invoice 4711",
        "the CLI crashes on ctrl-c",
        "share my ssn with the team",
    ]
    for case in cases:
        print(f"\n--- case: {case} ---")
        runner.trace = Span(name="run", attributes={"user_input": case[:40]})
        try:
            out = runner.run(triage, case)
            print(f"final: {out}")
        except GuardrailTripped as e:
            print(f"GUARDRAIL: {e}")
        print("span tree:")
        _print_span(runner.trace, indent=1)

    print()
    print("every handoff is a tool named transfer_to_<agent>.")
    print("every guardrail trip is a structured exception, not a crash.")


if __name__ == "__main__":
    main()

// Lesson: OpenAI Agents SDK: Handoffs, Guardrails, Tracing (phase 14 / lesson 16)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/14-agent-engineering/16-openai-agents-sdk/docs/en.md
// Run: npx tsx phases/14-agent-engineering/16-openai-agents-sdk/code/main.ts

export {};

type Attrs = Record<string, unknown>;

function pyStrRepr(s: string): string {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = "";
  for (const ch of s) {
    if (ch === "\\") out += "\\\\";
    else if (ch === quote) out += "\\" + ch;
    else if (ch === "\n") out += "\\n";
    else if (ch === "\t") out += "\\t";
    else if (ch === "\r") out += "\\r";
    else out += ch;
  }
  return quote + out + quote;
}

function pyRepr(v: unknown): string {
  if (typeof v === "string") return pyStrRepr(v);
  if (typeof v === "boolean") return v ? "True" : "False";
  if (v === null || v === undefined) return "None";
  if (Array.isArray(v)) return "[" + v.map(pyRepr).join(", ") + "]";
  if (typeof v === "object") {
    return "{" + Object.entries(v as Attrs).map(([k, x]) => `${pyStrRepr(k)}: ${pyRepr(x)}`).join(", ") + "}";
  }
  return String(v);
}

class GuardrailTripped extends Error {
  name = "GuardrailTripped";

  constructor(public which: string, public reason: string) {
    super(`${which}: ${reason}`);
  }
}

interface FunctionTool {
  name: string;
  description: string;
  fn: (args: Attrs) => string;
}

class Handoff {
  constructor(public target: Agent) {}

  get toolName(): string {
    return `transfer_to_${this.target.name}`;
  }
}

interface PolicyOutput {
  kind: string;
  text?: string;
  tool?: string;
  args?: Attrs;
  to?: string;
  input?: string;
}

interface Agent {
  name: string;
  instructions: string;
  policy: (input: string) => PolicyOutput;
  tools: FunctionTool[];
  handoffs: Handoff[];
}

interface Guardrail {
  name: string;
  check: (text: string) => [boolean, string];
}

class Span {
  children: Span[] = [];

  constructor(public name: string, public attributes: Attrs = {}) {}
}

class Runner {
  maxHops = 3;
  trace = new Span("run");

  constructor(public inputGuardrails: Guardrail[] = [], public outputGuardrails: Guardrail[] = []) {}

  run(agent: Agent, userInput: string): string {
    for (const guard of this.inputGuardrails) {
      const [ok, reason] = guard.check(userInput);
      this.trace.children.push(new Span(`input_guardrail.${guard.name}`, { passed: ok, reason }));
      if (!ok) throw new GuardrailTripped("input", reason);
    }

    let currentAgent = agent;
    let currentInput = userInput;
    let finalOutput = "";
    for (let hop = 0; hop < this.maxHops; hop++) {
      const agentSpan = new Span(`agent.${currentAgent.name}`, {
        hop,
        instructions: currentAgent.instructions.slice(0, 40),
      });
      this.trace.children.push(agentSpan);

      const policyOutput = currentAgent.policy(currentInput);
      const kind = policyOutput.kind;

      if (kind === "final") {
        finalOutput = policyOutput.text as string;
        agentSpan.children.push(new Span("llm_generation", { output: finalOutput.slice(0, 60) }));
        break;
      }
      if (kind === "tool") {
        const toolName = policyOutput.tool as string;
        const args = policyOutput.args ?? {};
        const tool = currentAgent.tools.find((t) => t.name === toolName);
        if (tool === undefined) {
          agentSpan.children.push(new Span("tool_error", { tool: toolName, reason: "unknown tool" }));
          finalOutput = `error: unknown tool ${toolName}`;
          break;
        }
        const result = tool.fn(args);
        agentSpan.children.push(new Span(`tool.${toolName}`, { args, result: result.slice(0, 40) }));
        currentInput = `tool ${toolName} returned: ${result}`;
        continue;
      }
      if (kind === "handoff") {
        const targetName = policyOutput.to as string;
        const handoff = currentAgent.handoffs.find((h) => h.target.name === targetName);
        if (handoff === undefined) {
          finalOutput = `error: no handoff to ${targetName}`;
          break;
        }
        agentSpan.children.push(new Span(`handoff.${handoff.toolName}`, { from: currentAgent.name, to: targetName }));
        currentAgent = handoff.target;
        currentInput = policyOutput.input ?? currentInput;
        continue;
      }
      finalOutput = `error: unknown policy kind ${kind}`;
      break;
    }

    for (const guard of this.outputGuardrails) {
      const [ok, reason] = guard.check(finalOutput);
      this.trace.children.push(new Span(`output_guardrail.${guard.name}`, { passed: ok, reason }));
      if (!ok) throw new GuardrailTripped("output", reason);
    }

    return finalOutput;
  }
}

function printSpan(span: Span, indent = 0): void {
  const prefix = "  ".repeat(indent);
  const attrs = Object.entries(span.attributes)
    .map(([k, v]) => `${k}=${pyRepr(v)}`)
    .join(" ");
  console.log(`${prefix}${span.name}  ${attrs}`);
  for (const child of span.children) printSpan(child, indent + 1);
}

function triagePolicy(userInput: string): PolicyOutput {
  const t = userInput.toLowerCase();
  if (t.includes("refund") || t.includes("billing") || t.includes("invoice")) {
    return { kind: "handoff", to: "billing", input: userInput };
  }
  if (t.includes("error") || t.includes("crash") || t.includes("bug")) {
    return { kind: "handoff", to: "support", input: userInput };
  }
  return { kind: "final", text: "i'm not sure how to help with that" };
}

function billingPolicy(userInput: string): PolicyOutput {
  return { kind: "final", text: `billing handled: ${userInput.slice(0, 40)}` };
}

function supportPolicy(userInput: string): PolicyOutput {
  return { kind: "final", text: `support handled: ${userInput.slice(0, 40)}` };
}

function piiCheck(text: string): [boolean, string] {
  if (text.toLowerCase().includes("ssn")) return [false, "refuses to process social security numbers"];
  return [true, "ok"];
}

function lengthCheck(text: string): [boolean, string] {
  return [text.length < 200, `output ${text.length} chars`];
}

function main(): void {
  console.log("=".repeat(70));
  console.log("OPENAI AGENTS SDK SHAPE: Phase 14, Lesson 16");
  console.log("=".repeat(70));

  const billing: Agent = {
    name: "billing",
    instructions: "handle refunds and invoices",
    policy: billingPolicy,
    tools: [],
    handoffs: [],
  };
  const support: Agent = {
    name: "support",
    instructions: "handle bugs and errors",
    policy: supportPolicy,
    tools: [],
    handoffs: [],
  };
  const triage: Agent = {
    name: "triage",
    instructions: "route queries to the right specialist",
    policy: triagePolicy,
    tools: [],
    handoffs: [new Handoff(billing), new Handoff(support)],
  };

  const runner = new Runner([{ name: "pii_block", check: piiCheck }], [{ name: "length_cap", check: lengthCheck }]);

  const cases = ["I need a refund for invoice 4711", "the CLI crashes on ctrl-c", "share my ssn with the team"];
  for (const c of cases) {
    console.log(`\n--- case: ${c} ---`);
    runner.trace = new Span("run", { user_input: c.slice(0, 40) });
    try {
      const out = runner.run(triage, c);
      console.log(`final: ${out}`);
    } catch (e) {
      if (!(e instanceof GuardrailTripped)) throw e;
      console.log(`GUARDRAIL: ${e.message}`);
    }
    console.log("span tree:");
    printSpan(runner.trace, 1);
  }

  console.log();
  console.log("every handoff is a tool named transfer_to_<agent>.");
  console.log("every guardrail trip is a structured exception, not a crash.");
}

main();
